import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import '../../viewmodels/tutor_view_model.dart';
import '../../theme/app_theme.dart';

class TutorContentScreen extends StatelessWidget {const TutorContentScreen({super.key});
@override Widget build(BuildContext context){final vm=context.watch<TutorViewModel>();return Scaffold(appBar:AppBar(title:const Text('Upload Content')),floatingActionButton:FloatingActionButton.extended(onPressed:()=>_add(context),icon:const Icon(Icons.add),label:const Text('Add content')),body:!vm.isReady?const Center(child:CircularProgressIndicator()):vm.workspace.content.isEmpty?const Center(child:Padding(padding:EdgeInsets.all(28),child:Column(mainAxisSize:MainAxisSize.min,children:[Icon(Icons.library_add_outlined,size:56,color:AppColors.blue),SizedBox(height:12),Text('No learning content yet',style:TextStyle(fontSize:18,fontWeight:FontWeight.bold)),SizedBox(height:6),Text('Add a study resource, worksheet, video link or notes for your learners.',textAlign:TextAlign.center,style:TextStyle(color:AppColors.textMuted))]))):ListView(padding:const EdgeInsets.all(16),children:vm.workspace.content.map((item)=>Card(child:ListTile(leading:CircleAvatar(backgroundColor:AppColors.blueSoft,child:Icon(item.type=='Video'?Icons.play_circle_outline:Icons.description_outlined,color:AppColors.blue)),title:Text(item.title),subtitle:Text('${item.subject} • ${item.type}${item.resourceUrl.isNotEmpty?'\n${item.resourceUrl}':''}'),isThreeLine:item.resourceUrl.isNotEmpty,trailing:IconButton(icon:const Icon(Icons.delete_outline),onPressed:()=>context.read<TutorViewModel>().removeContent(item.id)),))).toList()));}
Future<void> _add(BuildContext context)async{final title=TextEditingController(),subject=TextEditingController(),url=TextEditingController();String type='Study notes';final form=GlobalKey<FormState>();await showDialog(context:context,builder:(ctx)=>StatefulBuilder(builder:(ctx,setState)=>AlertDialog(title:const Text('Add learning content'),content:Form(key:form,child:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[TextFormField(controller:title,decoration:const InputDecoration(labelText:'Title'),validator:(v)=>v==null||v.trim().isEmpty?'Enter a title':null),TextFormField(controller:subject,decoration:const InputDecoration(labelText:'Subject'),validator:(v)=>v==null||v.trim().isEmpty?'Enter a subject':null),DropdownButtonFormField<String>(value:type,decoration:const InputDecoration(labelText:'Content type'),items:['Study notes','Worksheet','Past paper','Video'].map((e)=>DropdownMenuItem(value:e,child:Text(e))).toList(),onChanged:(v)=>setState(()=>type=v??type)),TextFormField(controller:url,decoration:const InputDecoration(labelText:'Resource link (optional)',hintText:'https://...'))]))),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:const Text('Cancel')),FilledButton(onPressed:(){if(!form.currentState!.validate())return;context.read<TutorViewModel>().addContent(title:title.text.trim(),subject:subject.text.trim(),type:type,resourceUrl:url.text.trim());Navigator.pop(ctx);},child:const Text('Add'))])));title.dispose();subject.dispose();url.dispose();}
}
